namespace hanmo::resident {namespace {
Integer serial(const StableId& id,const StableId& prefix){const auto lead=prefix+":";if(id.rfind(lead,0)!=0)return -1;const auto digits=id.substr(lead.size());Integer n=0;const auto p=std::from_chars(digits.data(),digits.data()+digits.size(),n);return p.ec==std::errc{}&&p.ptr==digits.data()+digits.size()&&n>0&&std::to_string(n)==digits?n:-1;}
auto key(const GrowthTacticLessonCommit& b){return std::tie(b.result_id,b.actor_id,b.kind,b.request_seq,b.revision,b.from_tick,b.advance);}
Status start_match(const GrowthTacticLessonStart& source,const StableId& actor,const CommitResult& result){const auto* effect=result.details?std::get_if<ActionStarted>(&result.details->data):nullptr;return result.ok&&result.kind=="tactic_lesson_start"&&actor==source.agreement.student_id&&result.tick==source.agreement.tick&&result.revision>0&&result.revision-1==source.agreement.revision&&effect&&effect->action_id==source.action_id?common_success():common_failure("TacticLessonActualStartResultRequired",source.action_id);}
// 只有原dispatcher/个人战实际调用advance_world的入口可产生教学时钟；variant本身不作时钟证明。
bool clock_kind(const StableId& kind){return kind=="advance"||kind=="player_plan_step"||kind=="wait"||kind=="travel_wait"||kind=="duel_start"||kind=="encounter_fight"||kind=="dialogue_confirm";}
bool direct_clock_kind(const StableId& kind){return kind=="advance"||kind=="player_plan_step"||kind=="wait"||kind=="travel_wait";}
bool personal_start_shape(const ReceiptDetails& d){const auto* p=std::get_if<PersonalReceipt>(&d.data);return p&&serial(p->battle_id,"battle")>0&&!p->round&&!p->outcome&&(d.field_order.empty()||d.field_order==FieldOrder{"battle_id"});}
Status closure_match(const GrowthTacticLessonCompletion& source,const StableId& actor,const CommitResult& result,bool advance,Integer from_tick){
 if(!result.ok||!result.details||result.tick!=source.tick||from_tick<0||from_tick>result.tick||result.tick-from_tick!=(advance?1:0))return common_failure("TacticLessonActualClosureResultRequired",source.source_fact_id);
 const auto* step=std::get_if<AdvanceDetails>(&result.details->data);
 if(advance){
  if(!clock_kind(result.kind)||source.reason=="student_cancelled")return common_failure("TacticLessonActualAdvanceRequired",source.source_fact_id);
  if(direct_clock_kind(result.kind)){const auto* done=step?step->completed_actions.find(source.action_id):nullptr;if(!done)return common_failure("TacticLessonActualAdvanceRequired",source.source_fact_id);return validate_growth_tactic_lesson_action_completion(source,*done);}
  // 原personal_access丢弃内部AdvanceDetails；此处仅核已由提交前后真时钟和完整本课史证明的有限外层形状。
  if(step)return common_failure("TacticLessonActualResultShapeMismatch",source.source_fact_id);
  if(personal_start_shape(*result.details))return common_success();
  if(result.kind=="dialogue_confirm"&&std::holds_alternative<Done>(result.details->data)&&result.details->field_order.empty())return common_success();
  return common_failure("TacticLessonActualHiddenAdvanceRequired",source.source_fact_id);
 }
 if(step)return common_failure("TacticLessonActualResultShapeMismatch",source.source_fact_id);
 if(source.reason=="student_cancelled")return result.kind=="tactic_lesson_cancel"&&actor==source.actor_id&&std::holds_alternative<Done>(result.details->data)&&result.details->field_order.empty()?common_success():common_failure("TacticLessonActualCancelRequired",source.source_fact_id);
 return source.reason=="student_dead"||source.reason=="teacher_dead"?common_success():common_failure("TacticLessonActualAdvanceRequired",source.source_fact_id);
}
}
Outcome<GrowthTacticLessonNewSources> growth_tactic_lesson_new_sources(const GrowthTacticLessonState& before,const GrowthTacticLessonState& after){
 auto a=validate_growth_tactic_lesson_shape(before),b=validate_growth_tactic_lesson_shape(after);if(!a.ok)return {false,{},a.error};if(!b.ok)return {false,{},b.error};GrowthTacticLessonNewSources out;
 // 比较完整旧载荷及字段序；不拿当前控制/余额或“仍未消费”推导本次新增源。
 const auto old=encode_growth_tactic_lessons(before),now=encode_growth_tactic_lessons(after);
 for(const auto* table:{"starts","credits","closures"}){const auto& a=*old.find(table)->as<BoundaryValue::Dict>();const auto& b=*now.find(table)->as<BoundaryValue::Dict>();if(a.size()>b.size())return {false,{},common_failure("TacticLessonPriorSourceChanged",table).error};for(std::size_t i=0;i<a.size();++i)if(a[i].first!=b[i].first)return {false,{},common_failure("TacticLessonPriorSourceOrderChanged",a[i].first).error};}
 for(const auto* table:{"starts","credits","closures"})for(const auto& row:*old.find(table)->as<BoundaryValue::Dict>()){const auto* next=now.find(table)->find(row.first);if(!next||!compare_boundary(row.second,*next).exact())return {false,{},common_failure("TacticLessonPriorSourceChanged",row.first).error};}
 for(const auto& row:before.starts.rows())if(row.second.commit.result_id.empty())return {false,{},common_failure("TacticLessonPriorSourceUnbound",row.first).error};
 for(const auto& row:before.closures.rows())if(row.second.commit.result_id.empty())return {false,{},common_failure("TacticLessonPriorSourceUnbound",row.first).error};
 for(const auto& row:after.starts.rows())if(!before.starts.find(row.first)){if(!row.second.commit.result_id.empty())return {false,{},common_failure("TacticLessonNewSourceAlreadyBound",row.first).error};out.starts.push_back(row.first);}
 for(const auto& row:after.closures.rows())if(!before.closures.find(row.first)){if(!row.second.commit.result_id.empty())return {false,{},common_failure("TacticLessonNewSourceAlreadyBound",row.first).error};out.closures.push_back(row.first);}return {true,std::move(out),{}};
}
Status validate_growth_tactic_lesson_result_bindings(const CommonStore& c,const GrowthTacticLessonState& state){
 auto valid=validate_growth_tactic_lesson_shape(state);if(!valid.ok)return valid;std::map<StableId,std::pair<GrowthTacticLessonCommit,Integer>> results;std::map<std::pair<StableId,Integer>,StableId> requests;std::map<StableId,Integer> start_counts,cancel_counts;
 auto check=[&](const StableId& id,const GrowthTacticLessonCommit& b,Integer tick)->Status{
  const auto n=serial(id,"tactic_lesson"),r=serial(b.result_id,"result");const auto* sequence=c.state().request_sequences.find(b.actor_id);if(n<1||r<=n||r>=c.state().next_instance_id||!c.actor(b.actor_id)||!sequence||b.request_seq<1||b.request_seq>*sequence||b.revision<1||b.revision>c.revision()||tick<0||tick>c.tick()||b.from_tick<0||b.from_tick>tick||tick-b.from_tick!=(b.advance?1:0))return common_failure("InvalidTacticLessonCommitBinding",id);
  auto previous=results.find(b.result_id);if(previous!=results.end()&&(key(previous->second.first)!=key(b)||previous->second.second!=tick))return common_failure("TacticLessonConflictingResultBinding",id);results[b.result_id]={b,tick};auto request=std::make_pair(b.actor_id,b.request_seq);auto prior=requests.find(request);if(prior!=requests.end()&&prior->second!=b.result_id)return common_failure("TacticLessonConflictingRequestBinding",id);requests[request]=b.result_id;
  for(const auto& h:c.state().history)if(h.result_id==b.result_id&&(h.actor_id!=b.actor_id||h.kind!=b.kind||h.tick!=tick))return common_failure("TacticLessonCommitHistoryMismatch",id);
  const auto cache_key=b.actor_id+":"+std::to_string(b.request_seq);const auto* cached=c.state().results.find(cache_key);if(cached&&(!*cached||(*cached)->result_id!=b.result_id||(*cached)->kind!=b.kind||(*cached)->revision!=b.revision||(*cached)->tick!=tick))return common_failure("TacticLessonCommitCacheMismatch",id);
  for(const auto& row:c.state().results.rows())if(row.second&&row.second->result_id==b.result_id&&row.first!=cache_key)return common_failure("TacticLessonCommitCacheMismatch",id);return common_success();
 };
 for(const auto& row:state.starts.rows()){const auto& s=row.second;const auto& b=s.commit;valid=check(row.first,b,s.agreement.tick);if(!valid.ok)return valid;if(b.advance||b.kind!="tactic_lesson_start"||b.actor_id!=s.agreement.student_id||b.revision-1!=s.agreement.revision||serial(s.action_id,"action")>=serial(row.first,"tactic_lesson")||++start_counts[b.result_id]!=1)return common_failure("TacticLessonStartBindingMismatch",row.first);const auto* cached=c.state().results.find(b.actor_id+":"+std::to_string(b.request_seq));if(cached){valid=start_match(s,b.actor_id,**cached);if(!valid.ok)return valid;}}
 for(const auto& row:state.closures.rows()){const auto& s=row.second;const auto& b=s.commit;valid=check(row.first,b,s.tick);if(!valid.ok)return valid;auto completion=read_growth_tactic_lesson_completion(c,state,row.first);if(!completion.ok)return {false,{},completion.error};const auto* start=state.starts.find(s.started_fact_id);if(serial(start->commit.result_id,"result")>=serial(row.first,"tactic_lesson")||start->commit.revision>=b.revision)return common_failure("TacticLessonClosureBeforeAcceptedStart",row.first);if((b.advance&&!clock_kind(b.kind))||(!b.advance&&(s.reason=="completed"||s.reason=="student_unavailable"||s.reason=="teacher_unavailable"))||(s.reason=="student_cancelled"&&(b.advance||b.kind!="tactic_lesson_cancel"||b.actor_id!=completion.value.actor_id||++cancel_counts[b.result_id]!=1)))return common_failure("TacticLessonClosureBindingMismatch",row.first);const auto* cached=c.state().results.find(b.actor_id+":"+std::to_string(b.request_seq));if(cached){valid=closure_match(completion.value,b.actor_id,**cached,b.advance,b.from_tick);if(!valid.ok)return valid;}}
 // 每条保留命令结果反查原绑定；不是只从账向cache单向检查。
 for(const auto& row:c.state().results.rows()){if(!row.second)continue;const auto& r=*row.second;if((r.kind=="tactic_lesson_start"&&start_counts[r.result_id]!=1)||(r.kind=="tactic_lesson_cancel"&&cancel_counts[r.result_id]!=1))return common_failure("TacticLessonCachedCommandSourceMissing",r.result_id);const auto* advance=r.details?std::get_if<AdvanceDetails>(&r.details->data):nullptr;if(!advance)continue;for(const auto& done:advance->completed_actions.rows())for(const auto& start:state.starts.rows())if(start.second.action_id==done.first){Integer found=0;for(const auto& end:state.closures.rows())if(end.second.action_id==done.first&&end.second.commit.result_id==r.result_id)++found;if(found!=1)return common_failure("TacticLessonCachedCompletionSourceMissing",r.result_id);}}
 return common_success();
}
Status bind_growth_tactic_lesson_result_in_candidate(CommonStore& c,GrowthTacticLessonState& state,const GrowthTacticLessonNewSources& sources,const StableId& actor,Integer sequence,const CommitResult& result,Integer from_tick){
 const auto* cached=c.state().results.find(actor+":"+std::to_string(sequence));const auto* seq=c.state().request_sequences.find(actor);if(!cached||cached->get()!=&result||!seq||*seq!=sequence||!result.ok||!result.details||result.tick!=c.tick()||result.revision!=c.revision()||c.state().history.empty()||from_tick<0||from_tick>c.tick()||c.tick()-from_tick>1)return common_failure("TacticLessonActualCachedResultRequired",result.result_id);const auto& h=c.state().history.back();if(h.result_id!=result.result_id||h.actor_id!=actor||h.kind!=result.kind||h.tick!=result.tick)return common_failure("TacticLessonActualCachedHistoryRequired",result.result_id);const bool advance=result.tick>from_tick;std::set<StableId> seen;std::vector<std::pair<GrowthTacticLessonCommit*,GrowthTacticLessonCommit>> writes;
 for(const auto& id:sources.starts){auto* s=state.starts.find(id);if(!s||!s->commit.result_id.empty()||!seen.insert(id).second)return common_failure("TacticLessonNewStartRequired",id);if(advance||from_tick!=s->agreement.tick)return common_failure("TacticLessonEnrollmentMustBeZeroTime",id);auto match=start_match(*s,actor,result);if(!match.ok)return match;writes.emplace_back(&s->commit,s->commit);}
 for(const auto& id:sources.closures){auto* s=state.closures.find(id);if(!s||!s->commit.result_id.empty()||!seen.insert(id).second)return common_failure("TacticLessonNewClosureRequired",id);auto source=read_growth_tactic_lesson_completion(c,state,id);if(!source.ok)return {false,{},source.error};auto match=closure_match(source.value,actor,result,advance,from_tick);if(!match.ok)return match;writes.emplace_back(&s->commit,s->commit);}
 for(const auto& row:state.starts.rows())if(row.second.commit.result_id.empty()&&!seen.count(row.first))return common_failure("TacticLessonUnboundStart",row.first);for(const auto& row:state.closures.rows())if(row.second.commit.result_id.empty()&&!seen.count(row.first))return common_failure("TacticLessonUnboundClosure",row.first);
 for(auto& w:writes){w.first->result_id=result.result_id;w.first->actor_id=actor;w.first->kind=result.kind;w.first->request_seq=sequence;w.first->revision=result.revision;w.first->from_tick=from_tick;w.first->advance=advance;}auto valid=validate_growth_tactic_lesson_result_bindings(c,state);if(!valid.ok)for(const auto& w:writes)*w.first=w.second;return valid;
}
Outcome<std::vector<GrowthTacticLessonCompletion>> read_growth_tactic_lesson_completions_for_result(const CommonStore& c,const GrowthTacticLessonState& state,const CommitResult& result){bool exact=false;for(const auto& row:c.state().results.rows())if(row.second.get()==&result)exact=true;if(!exact)return {false,{},common_failure("TacticLessonActualCachedResultRequired",result.result_id).error};auto valid=validate_growth_tactic_lesson_result_bindings(c,state);if(!valid.ok)return {false,{},valid.error};std::vector<GrowthTacticLessonCompletion> out;for(const auto& row:state.closures.rows())if(row.second.commit.result_id==result.result_id){auto source=read_growth_tactic_lesson_completion(c,state,row.first);if(!source.ok)return {false,{},source.error};out.push_back(std::move(source.value));}return {true,std::move(out),{}};}
}
